    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "snowText",
                name = "klexicon",
                version = c(1,0,0),
                options = options,
                results = klexiconResults$new(options=options),
                data = data,
                datasetId = datasetId,
