#' Korean Lexicon Analysis
#'
#' Performs dictionary-based text analysis with Korean-oriented matching 
#' rules. User-defined categories support exact terms, prefix wildcards, and 
#' multi-word expressions. Optional Korean negation handling identifies and 
#' adjusts lexicon matches occurring with nearby negation cues.
#' @param data .
#' @param textVar .
#' @param lexicon Four example categories are provided by default. Users may
#'   freely edit, remove, or add categories. Enter terms as a comma-separated
#'   list. A trailing * indicates prefix matching. Multi-word expressions are
#'   allowed.
#' @param normalizeKorean .
#' @param negationMode .
#' @param negationWindow .
#' @param negationCues Enter Korean negation cues as a comma-separated list. A
#'   trailing * indicates prefix matching.
#' @param documentDetails .
#' @param negationEvidence .
#' @param categoryPlot .
#' @param negationImpactPlot .
#' @param cooccurrence Counts documents in which both categories have at least
#'   one adjusted match.
#' @param cooccurrencePlot .
#' @param prevalencePlot Displays the percentage of documents with at least
#'   one adjusted match in each category.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dictSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$matchingSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$catSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$documentDetails} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$negationEvidence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cooccurrence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$statusNote} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$categoryPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$negationImpactPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cooccurrencePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$prevalencePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$saveResults} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$detectedWords} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dictSummary$asDF}
#'
#' \code{as.data.frame(results$dictSummary)}
#'
#' @export
klexicon <- function(
    data,
    textVar,
    lexicon = list(
                list(category="\uAE0D\uC815 \uC815\uC11C", terms="\uC88B*, \uB9CC\uC871*, \uD589\uBCF5*, \uAE30\uC058*, \uCD94\uCC9C*"),
                list(category="\uBD80\uC815 \uC815\uC11C", terms="\uB098\uC058*, \uC2E4\uB9DD*, \uBD88\uB9CC*, \uBD88\uD3B8*, \uC2EB*"),
                list(category="\uBD88\uC548", terms="\uBD88\uC548*, \uAC71\uC815*, \uB450\uB835*, \uAE34\uC7A5*, \uCD08\uC870*"),
                list(category="\uC131\uCDE8", terms="\uC131\uACF5*, \uC131\uCDE8*, \uB2EC\uC131*, \uD5A5\uC0C1*, \uBC1C\uC804*")),
    normalizeKorean = TRUE,
    negationMode = "exclude",
    negationWindow = 1,
    negationCues = "\uC54A*, \uBABB*, \uC548",
    documentDetails = FALSE,
    negationEvidence = FALSE,
    categoryPlot = FALSE,
    negationImpactPlot = FALSE,
    cooccurrence = FALSE,
    cooccurrencePlot = FALSE,
    prevalencePlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("klexicon requires jmvcore to be installed (restart may be required)")

    if ( ! missing(textVar)) textVar <- jmvcore::resolveQuo(jmvcore::enquo(textVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(textVar), textVar, NULL))


    options <- klexiconOptions$new(
        textVar = textVar,
        lexicon = lexicon,
        normalizeKorean = normalizeKorean,
        negationMode = negationMode,
        negationWindow = negationWindow,
        negationCues = negationCues,
        documentDetails = documentDetails,
        negationEvidence = negationEvidence,
        categoryPlot = categoryPlot,
        negationImpactPlot = negationImpactPlot,
        cooccurrence = cooccurrence,
        cooccurrencePlot = cooccurrencePlot,
        prevalencePlot = prevalencePlot)

    analysis <- klexiconClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

